// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *FinanceChargeTerms) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FinanceChargeTermsTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (code)`,
		fmt.Sprintf("%s$Finance_Charge_Terms$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range financeChargeTermsSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, FinanceChargeTermsTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, FinanceChargeTermsTableName, keys)
}

// financeChargeTermsSIFTSpecs are the table's keys with sum_index_fields
func financeChargeTermsSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *FinanceChargeTerms) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, FinanceChargeTermsTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range financeChargeTermsSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, FinanceChargeTermsTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: FinanceChargeTermsTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, FinanceChargeTermsTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

