// Insert inserts the record into the database
func (t *FinanceChargeTerms) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FinanceChargeTermsTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Code,
		t.Interest_rate,
		t.Minimum_amount_lcy,
		t.Additional_fee_lcy,
		t.Description,
		t.Interest_calculation_method,
		t.Interest_period_days,
		t.Grace_period,
		t.Due_date_calculation,
		t.Interest_calculation,
		t.Post_interest,
		t.Post_additional_fee,
		t.Line_description,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (code, interest_rate, minimum_amount_lcy, additional_fee_lcy, description, interest_calculation_method, interest_period_days, grace_period, due_date_calculation, interest_calculation, post_interest, post_additional_fee, line_description) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (code) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Finance_Charge_Terms: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(FinanceChargeTermsTableName, key)
		return false
	}
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *FinanceChargeTerms) InsertAll(records []*FinanceChargeTerms, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Code,
			r.Interest_rate,
			r.Minimum_amount_lcy,
			r.Additional_fee_lcy,
			r.Description,
			r.Interest_calculation_method,
			r.Interest_period_days,
			r.Grace_period,
			r.Due_date_calculation,
			r.Interest_calculation,
			r.Post_interest,
			r.Post_additional_fee,
			r.Line_description,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FinanceChargeTermsTableName)
	columns := []string{"code", "interest_rate", "minimum_amount_lcy", "additional_fee_lcy", "description", "interest_calculation_method", "interest_period_days", "grace_period", "due_date_calculation", "interest_calculation", "post_interest", "post_additional_fee", "line_description"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

