// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *FinanceChargeTerms) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, FinanceChargeTermsTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "interest_rate":
			column = "interest_rate"
		case "minimum_amount_lcy":
			column = "minimum_amount_lcy"
		case "additional_fee_lcy":
			column = "additional_fee_lcy"
		case "interest_period_days":
			column = "interest_period_days"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Finance_Charge_Terms", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Finance_Charge_Terms.%s: %w", column, err)
		}
		switch column {
		case "interest_rate":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Finance_Charge_Terms.%s: %w", column, err)
			}
			t.Interest_rate = d
		case "minimum_amount_lcy":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Finance_Charge_Terms.%s: %w", column, err)
			}
			t.Minimum_amount_lcy = d
		case "additional_fee_lcy":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Finance_Charge_Terms.%s: %w", column, err)
			}
			t.Additional_fee_lcy = d
		case "interest_period_days":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Finance_Charge_Terms.%s: %w", column, err)
			}
			t.Interest_period_days = int(f)
		}
	}
	return nil
}

